import sys

def solve():
    tokens = sys.stdin.read().split()
    n = int(tokens[0])
    s = tokens[1]
    e = [int(x) - 1 for x in tokens[2:2 + n]]

    first_g = s.index('G')
    last_g = s.rindex('G')
    first_h = s.index('H')
    last_h = s.rindex('H')

    g_all = e[first_g] >= last_g
    h_all = e[first_h] >= last_h

    ans = 0
    g_ok = g_all or (first_g < first_h <= e[first_g])
    h_ok = h_all or (first_h < first_g <= e[first_h])
    if g_ok and h_ok:
        ans += 1

    if h_all:
        for i in range(first_h):
            if i != first_g and s[i] == 'G' and e[i] >= first_h:
                ans += 1

    if g_all:
        for j in range(first_g):
            if j != first_h and s[j] == 'H' and e[j] >= first_g:
                ans += 1

    print(ans)

if __name__ == "__main__":
    solve()

