#include <iostream>
#include <string>
#include <vector>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    string s;
    cin >> n >> s;
    vector<int> e(n);
    for (int i = 0; i < n; i++) { cin >> e[i]; e[i]--; }

    int firstG = -1, lastG = -1, firstH = -1, lastH = -1;
    for (int i = 0; i < n; i++) {
        if (s[i] == 'G') {
            if (firstG == -1) firstG = i;
            lastG = i;
        } else {
            if (firstH == -1) firstH = i;
            lastH = i;
        }
    }

    bool gAll = e[firstG] >= lastG;
    bool hAll = e[firstH] >= lastH;
    long long ans = 0;
    bool gOk = gAll || (firstG < firstH && e[firstG] >= firstH);
    bool hOk = hAll || (firstH < firstG && e[firstH] >= firstG);
    if (gOk && hOk) ans++;

    if (hAll) {
        for (int i = 0; i < firstH; i++) {
            if (i != firstG && s[i] == 'G' && e[i] >= firstH) ans++;
        }
    }
    if (gAll) {
        for (int j = 0; j < firstG; j++) {
            if (j != firstH && s[j] == 'H' && e[j] >= firstG) ans++;
        }
    }
    cout << ans << '\n';
    return 0;
}

