    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(br.readLine().trim());
        String s = br.readLine().trim();
        StringTokenizer st = new StringTokenizer(br.readLine());
        int[] e = new int[n];
        for (int i = 0; i < n; i++) e[i] = Integer.parseInt(st.nextToken()) - 1;

        int firstG = s.indexOf('G'), lastG = s.lastIndexOf('G');
        int firstH = s.indexOf('H'), lastH = s.lastIndexOf('H');

        boolean gAll = e[firstG] >= lastG;
        boolean hAll = e[firstH] >= lastH;
        long ans = 0;
        boolean gOk = gAll || (firstG < firstH && e[firstG] >= firstH);
        boolean hOk = hAll || (firstH < firstG && e[firstH] >= firstG);
        if (gOk && hOk) ans++;

        if (hAll) {
            for (int i = 0; i < firstH; i++) {
                if (i != firstG && s.charAt(i) == 'G' && e[i] >= firstH) ans++;
            }
        }
        if (gAll) {
            for (int j = 0; j < firstG; j++) {
                if (j != firstH && s.charAt(j) == 'H' && e[j] >= firstG) ans++;
            }
        }
        System.out.println(ans);
    }
}

